.ofcb-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ofcb-root,.ofcb-root *,.ofcb-root *::before,.ofcb-root *::after{box-sizing:border-box}
.ofcb-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ofcb-root img{display:block;border:0;max-width:none}
.ofcb-root > [data-node-id]{will-change:transform}
.ofcb-root [hidden]{display:none!important}
.ofcb-root [data-sh-theme="dark"]{display:none!important}
.ofcb-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.ofcb-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.ofcb-root .n145_11580{align-content:stretch;display:flex;gap:10px;align-items:center;padding-top:8px;padding-bottom:8px;position:relative;border-radius:8px;flex-shrink:0;width:100%}
.ofcb-root .n145_11581{position:relative;flex-shrink:0;width:21.913px;height:21.913px}
.ofcb-root .x8{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.ofcb-root .n145_11583{word-break:break-word;flex:1 0 0;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:21.913px;min-width:1px;font-style:normal;position:relative;font-size:18px;color:color-mix(in srgb, var(--wa-text, rgb(253 253 253)) 80%, transparent);letter-spacing:-0.36px}
.ofcb-root .n145_11584{display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0}
.ofcb-root .x9{flex:none;transform:rotate(180deg)}
.ofcb-root .x10{position:relative;width:17.53px;height:17.53px}
.ofcb-root .x11{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.ofcb-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.ofcb-root[data-theme="dark"] [data-name="Input"],.ofcb-root[data-theme="dark"] [data-name="Select"],.ofcb-root[data-theme="dark"] [data-name^="Dropdown/Select"]{background-color:var(--wa-bg, #111316)}
